mapper.select:
SELECT a.*,s.id as img_id, s.name as img_name, s.file_url as  img_file_url,
	   s.save_type as img_save_type, s.file_type_index as img_file_type_index,s.file_type as fileType
FROM gc_access a
		left join sys_file s on s.id = a.package_img_id
where a.package_name is not null and a.master_id=#{masterId} and a.package_show_flag!=#{showFlag}

	AND a.id IN

		#{packageId}



	AND a.id not IN

		#{subscriptionId}


order by a."order"

select * from gc_access ac
left join gc_user_access ua on ac.id = ua.access_id and ua.user_id = #{userId}
where ac.master_id = #{masterId}
and ac.group_name is not null
and ua.user_id = #{userId}

select * from gc_access ac
left join gc_user_access ua on ac.id = ua.access_id and ua.user_id = #{userId}
where ua.master_id = #{masterId}
and ac.group_name is not null
and ua.user_id = #{userId}
and (ua.role_json::text like concat('%','groupAdmin','%')
    or
    ua.role_json::text like concat('%','orgAdmin','%')
)

	and ac.group_name like concat('%',#{name},'%')

select * from gc_access
where master_id = #{masterId}

	AND code IN

		#{code}

SELECT content_group_info.*, coalesce(course_assignment.assignment_count, 0) as subjectNum
FROM (
select coalesce(json_array_length(subscribe_json),0) as channelNum,ac.*
,u.id as u_id,f.id as f_id,f.name as f_name,f.file_url as f_file_url,f.save_type as f_save_type,
ui.id as info_id,ui.first_name as firstName ,ui.last_name as lastName,ui.avatar_file_id as avatarFileId,
u.username as username
from gc_access ac
left join  gc_user_access ua on ua.access_id = ac.id
left join gc_user u on u.id = ua.user_id
left join gc_user_info ui on u.info_id = ui.id
left join sys_file f on ui.avatar_file_id=f.id
where ac.master_id = #{query.masterId}

	and u.id = #{query.userId}

and (ua.role_json::text like concat('%','Admin','%')
or ua.role_json::text like concat('%','superadmin','%')
)

	and group_name like concat('%',#{query.name},'%')

) as content_group_info
LEFT JOIN (
SELECT content_group_id, COUNT(id) as assignment_count
FROM gc_content_group_course_assignment
GROUP BY content_group_id
) as course_assignment ON content_group_info.id = course_assignment.content_group_id


		order by content_group_info.channelNum ${query.order}


		order by subjectNum ${query.order}


		order by content_group_info.group_name ${query.order}

select ga.*
from gc_access ga
		 JOIN gc_content_group_course_assignment gcca ON ga.id = gcca.content_group_id
where 1=1
  and ga.master_id = #{masterId}
  and gcca.course_id = #{id}

select * from gc_access
where master_id = #{masterId}
  and (channel_json::jsonb @> to_jsonb(#{id}::integer) or subscribe_json::jsonb @> to_jsonb(#{id}::integer))

select * from gc_access
where (channel_json::jsonb @> to_jsonb(#{ptId}::integer) or subscribe_json::jsonb @> to_jsonb(#{ptId}::integer))
  and master_id = #{masterId}

select * from gc_access
where id in

	#{id}

select ga.*
from gc_access ga
		 join gc_content_group_course_assignment gcca on ga.id = gcca.content_group_id
WHERE ga.master_id = #{masterId}
and gcca.course_id = #{subId}

select ac.*,ua.parent_code from gc_access ac
	left join gc_user_access ua on ua.access_id = ac.id
where
	ua.master_id= #{masterId}
  and ua.user_id = #{userId}
  and ac.group_name is not null
  and (ua.role_json::text like concat('%','groupAdmin','%')
	or
	   ua.role_json::text like concat('%','orgAdmin','%')
	)

SELECT count(gcca_may.id) + count(gcca_must.id) as subjectNum, ac.id, ac.master_id, ac.role_type, ac.admin_id, ac.code, ac.package_learning_hours, ac.subject_json, ac.update_time, ac.create_time, ac.code_type, ac.free_flag, ac.package_name, ac.channel_json, ac.group_name, ac.subscribe_json, ac.role_json, uap.may_subject_json as may_subject_json, uap.must_subject_json as must_subject_json FROM gc_access ac LEFT JOIN gc_user_access ua ON ac.id = ua.access_id AND ua.user_id = #{userId} left join gc_user_access_permission uap on uap.user_access_id = ua.id left join gc_content_group_course_assignment gcca_must on ac.id = gcca_must.content_group_id AND gcca_must.is_mandatory = 1 left join gc_content_group_course_assignment gcca_may on ac.id = gcca_may.content_group_id AND gcca_may.is_mandatory = 0 WHERE ac.master_id = #{masterId} AND ac.group_name IS NOT NULL AND ua.user_id = #{userId}
and ac.group_name like concat('%',#{name},'%')
GROUP BY ac.id, uap.id order by ac.group_name asc
